__NUXT_JSONP__("/jp/westwood", (function(a,b){return {data:[{details:{slug:a,pageTitle:"ウエストウッド校 | Mentor Language Institute",pageDescription:b,title:"ウエストウッド校",image:"\u002Fimages\u002Flocation\u002Fwestwood\u002Fwestwood-campus.jpg",yt_link:"https:\u002F\u002Fwww.youtube.com\u002Fembed\u002FddE5HSu4VGE",subtitle:[b,"ウェストウッドはロサンゼルスの中心地、名門大学UCLAがあることでも知られており、MLIはキャンパスはそのふもと、Wilshiere BlvdおよびWestwood Blvdの交差点の一角にあります。この交差点はWestwoodのバスのターミナルでキャンパスを出てバス停まで徒歩1分の好立地です。","また、このエリアは学生街とビジネスエリアが融合した街。学生価格から高級なお店まで点在し、留学生が生活しやすいエリアとなっています。"],landmark:[{image:"\u002Fimages\u002Flocation\u002Fwestwood\u002Fsanta-monica.jpg",title:"サンタモニカからバスで20分"},{image:"\u002Fimages\u002Flocation\u002Fwestwood\u002Fbeverly-hills.jpg",title:"ビバリーヒルズまでバスで10分"},{image:"\u002Fimages\u002Flocation\u002Fwestwood\u002Flos-angeles-skyline.jpg",title:"ダウンタウンまでバスで60分"}],gallery:{title:"ウエストウッドキャンパスの様子",subtitle:"キャンパスの様子を写真で紹介していきます。",photos:[{image:"\u002Fimages\u002Flocation\u002Fwestwood\u002F10880-building.jpg",title:"ビルの1階にあります。エレベーターに乗ることなくクラスまでは入れます。"},{image:"\u002Fimages\u002Flocation\u002Fwestwood\u002Ffront-desk.jpg",title:"受付はこちら。"},{image:"\u002Fimages\u002Flocation\u002Fwestwood\u002Fclassroom.jpg",title:"ガラス張りのクラスルーム"},{image:"\u002Fimages\u002Flocation\u002Fwestwood\u002Fcomputer-room.jpg",title:"テスト対策コースではコンピュータを使った授業も"},{image:"\u002Fimages\u002Flocation\u002Fwestwood\u002Fstudent-lounge.jpg",title:"スチューデントラウンジ"},{image:"\u002Fimages\u002Flocation\u002Fwestwood\u002Ffree-space.jpg",title:"フリースペース。クラスメイトとの会話や自習などに利用されています"}]},location:{title:"Location",map_link:"https:\u002F\u002Fwww.google.com\u002Fmaps\u002Fembed?pb=!1m18!1m12!1m3!1d3305.4289041796537!2d-118.44512238478478!3d34.05851788060419!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x80c2bb7e2b42fadf%3A0xad96227841e11efb!2s10880+Wilshire+Blvd%2C+Los+Angeles%2C+CA+90024!5e0!3m2!1sen!2sus!4v1513884279258"},video:[{title:"1. MLIウエストウッドキャンパスへのバスでの行き方",youtube:"https:\u002F\u002Fwww.youtube.com\u002Fembed\u002FV2zydV7aWvA"},{title:"2. MLIウエストウッドキャンパスへの車での行き方",youtube:"https:\u002F\u002Fwww.youtube.com\u002Fembed\u002F5FXkkyV3DZg"}],environment:{title:"周辺環境",photos:[{image:"\u002Fimages\u002Flocation\u002Fwestwood\u002Fucla.jpg",title:"UCLAまでは徒歩圏内。"},{image:"\u002Fimages\u002Flocation\u002Fwestwood\u002Fhammer-museum.jpg",title:"目の前にはロサンゼルスで有名な美術館ハマーミュージアム。"},{image:"\u002Fimages\u002Flocation\u002Fwestwood\u002Fwestwood-library.jpg",title:"裏には図書館があります。ここで宿題もできます。"},{image:"\u002Fimages\u002Flocation\u002Fwestwood\u002Fchevron-restaurant.jpg",title:"学生街のウェストウッドにはお求めやすいレストランも多数あります。"}]},accommodation:{title:"滞在について",description:["MLIウェストウッド校では滞在方法としてホームステイと学生寮を提供しております。"],types:[{desc:["＜学生寮＞\u003Cbr \u002F\u003E40部屋の学生寮があり、徒歩・またはバスで通学が可能です。"],yt_link:"https:\u002F\u002Fwww.youtube.com\u002Fembed\u002FV_eNdjw6Z1c"},{desc:["＜ホームステイ＞\u003Cbr \u002F\u003Eホームステイはアメリカの文化に触れる、ネイティブ英語を話す機会を増やすという意味で最適な方法です。"],yt_link2:"https:\u002F\u002Fwww.youtube.com\u002Fembed\u002FK4DT7WEI7MY",other_desc:["※動画は実際のホストファミリーですが、どのファミリーにアサインされるかの選択は出来ませんので予めご了承下さい。","\u003Ca href=\"\u002Fjp\u002Fstay\u002F\"\u003E滞在先の詳細はこちら\u003C\u002Fa\u003E"]}]},message:{title:"ディレクターの声",image:"\u002Fimages\u002Flocation\u002Fwestwood\u002Fwestwood-director.jpg",description:["ウェストウッド校はUCLAの傍にあることもあって、学生にとってはとても便利な場所にあります。勉強はもちろん映画や買い物、美術館など様々な楽しみがここにはあります。ここは場所がらからか、進学を目指す生徒も多く、TOEFLコースが人気です。また、このエリアにあってこの価格は驚き。他校から転校してくる人も多いのですよ！ぜひまずは資料をダウンロードして詳細を調べてみてください。"]},dl_links:"資料ダウンロードはこちら",dir:"\u002Fwestwood",path:"\u002Fwestwood\u002Fjp",extension:".json",createdAt:"2026-10-22T16:31:31.415Z",updatedAt:"2025-05-26T12:06:28.047Z"},lang:a}],fetch:{},mutations:void 0}}("jp","MLIの本校はロサンゼルスに住む人なら誰もが知るウェストウッドにあります。")));